import * as wt from 'node:worker_threads';

async function main(): Promise<void> {
  console.log('isInternalThread main', wt.isInternalThread);
  const worker = new wt.Worker(`
    const wt = require('node:worker_threads');
    const keep = setInterval(() => {}, 1000);
    wt.parentPort.postMessage('isInternalThread in worker ' + wt.isInternalThread + ' threadId ' + wt.threadId);
  `, { eval: true });
  let message: any = undefined;
  await new Promise<void>((resolve: () => void): void => { worker.once('message', (m: any) => { message = m; resolve(); }); });
  console.log(message);
  const attempt1 = async (): Promise<void> => { try { await wt.postMessageToThread(99, 1, [], 'soon'); console.log('timeout type', 'resolved', undefined); } catch (e: any) { console.log('timeout type', e.name, e.code, JSON.stringify(e.message)); } };
  await attempt1();
  const attempt2 = async (): Promise<void> => { try { await wt.postMessageToThread(99, 1, [], -1); console.log('timeout range', 'resolved', undefined); } catch (e: any) { console.log('timeout range', e.name, e.code, JSON.stringify(e.message)); } };
  await attempt2();
  const attempt3 = async (): Promise<void> => { try { await wt.postMessageToThread(99, 1, [], 0); console.log('timeout zero unknown', 'resolved', undefined); } catch (e: any) { console.log('timeout zero unknown', e.name, e.code, JSON.stringify(e.message)); } };
  await attempt3();
  await worker.terminate();
  console.log('done');
}
